        {"kind": "log", "sql": "SELECT COUNT(*) AS n FROM abnormal_logs WHERE service_name='ts-preserve-service' AND level='SEVERE' AND message LIKE '%I/O error on POST request for%ts-order-service%Unexpected end of file%'", "claim": "Preserve logs about 540 SEVERE errors: POST to ts-order-service cut with Unexpected end of file."}
